(() => {
  // src/js/form/api.js
  var schemaUrl = "/api/sections";
  var fieldsUrl = "/api/fields";
  async function schema() {
    const res = await fetch(schemaUrl);
    const data = await res.json();
    return data;
  }
  async function fields() {
    const res = await fetch(fieldsUrl);
    const data = await res.json();
    return data;
  }

  // src/js/html/maker.js
  function textarea(field, handler) {
    const fragment = document.createDocumentFragment();
    const label = addLabel(field);
    const textarea2 = document.createElement("textarea");
    textarea2.id = field.id;
    textarea2.name = field.id;
    textarea2.placeholder = field.placeholder;
    textarea2.addEventListener("input", handler);
    setAttrs(field, textarea2);
    fragment.appendChild(label);
    fragment.appendChild(textarea2);
    return fragment;
  }
  function select(field) {
    const fragment = document.createDocumentFragment();
    const label = addLabel(field);
    const select2 = document.createElement("select");
    select2.id = field.id;
    select2.name = field.id;
    setAttrs(field, select2);
    const defOp = document.createElement("option");
    defOp.value = "";
    defOp.textContent = "-- Selecciona --";
    defOp.disabled = true;
    defOp.selected = true;
    defOp.hidden = true;
    select2.appendChild(defOp);
    field.options.forEach((op) => {
      const option = document.createElement("option");
      option.value = op;
      option.textContent = op;
      select2.appendChild(option);
    });
    fragment.appendChild(label);
    fragment.appendChild(select2);
    return fragment;
  }
  function text(field, handler) {
    const fragment = document.createDocumentFragment();
    const text2 = document.createElement("input");
    const label = addLabel(field);
    text2.type = "text";
    if (field.placeholder) text2.placeholder = field.placeholder;
    text2.name = field.id;
    text2.id = field.id;
    text2.addEventListener("input", handler);
    setAttrs(field, text2);
    fragment.appendChild(label);
    fragment.appendChild(text2);
    return fragment;
  }
  function radios(field) {
    const contanier = document.createElement("div");
    field.options.forEach((op) => {
      const optionId = `${field.id}_${op}`;
      const div = document.createElement("div");
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.type = "radio";
      input.id = optionId;
      input.name = field.id;
      input.value = op;
      setAttrs(field, input);
      div.appendChild(input);
      label.setAttribute("for", optionId);
      label.textContent = op;
      div.appendChild(label);
      div.style = "display: flex; gap: 10px;";
      contanier.appendChild(div);
    });
    return contanier;
  }
  function pills(field, handler) {
    const fragment = document.createDocumentFragment();
    const label = addLabel(field);
    const pillsDiv = document.createElement("div");
    const input = document.createElement("input");
    const note = document.createElement("p");
    note.textContent = "Separa cada elemento con una coma ( , )";
    pillsDiv.setAttribute("pills-container", "");
    pillsDiv.id = `${field.id}_pills`;
    input.type = "text";
    input.id = field.id;
    input.name = field.id;
    input.placeholder = field.placeholder;
    input.setAttribute("pills-input", "");
    input.addEventListener("input", handler);
    setAttrs(field, input);
    fragment.appendChild(label);
    fragment.appendChild(note);
    fragment.appendChild(pillsDiv);
    fragment.appendChild(input);
    return fragment;
  }
  function pill(value) {
    const pill2 = document.createElement("span");
    pill2.textContent = value;
    return pill2;
  }
  function dynCL(field) {
    const fragment = document.createDocumentFragment();
    const optionsDiv = document.createElement("div");
    optionsDiv.id = field.id;
    optionsDiv.setAttribute("dynCL-options", "");
    fragment.appendChild(optionsDiv);
    return fragment;
  }
  function addLabel(field) {
    const label = document.createElement("label");
    label.textContent = field.label;
    if (field.required === true) {
      const star = document.createElement("span");
      star.textContent = "*";
      label.appendChild(star);
    }
    label.htmlFor = field.id;
    return label;
  }
  function setAttrs(field, input) {
    if (field.required === true) input.required = true;
    if ("minLength" in field) input.setAttribute("minLength", field.minLength);
    if ("maxLength" in field) input.setAttribute("maxLength", field.maxLength);
  }

  // src/js/logic/state.js
  var state = {};
  function setFieldValue(fieldId, value) {
    state[fieldId] = value;
  }
  async function useState() {
    const fields2 = await fields();
    fields2.forEach((field) => {
      if (field.id === "nombre" || field.id === "email") return;
      state[field.id] = "";
    });
    return state;
  }
  var state_default = useState;

  // src/js/logic/stateHandling.js
  var state2 = {};
  (async function setState() {
    state2 = await state_default();
  })();
  var change = (e) => {
    const input = e.target;
    setFieldValue(input.id, input.value);
    console.log(state2);
  };
  var changePill = (input, value) => {
    setFieldValue(input.id, value);
    console.log(state2);
  };

  // src/js/logic/pillsLogic.js
  function pillsLogic(e) {
    const input = e.target;
    if (e.data === ",") {
      const value = input.value.slice(0, -1).trim();
      const isValid = /^[A-Za-zÁÉÍÓÚáéíóúÑñ0-9 ]+$/.test(value);
      if (value === ",") return;
      if (!isValid) return;
      appendPill(input, value);
      savePillsToState(input);
      input.value = "";
    }
  }
  function appendPill(input, value) {
    const query = `[pills-container]#${input.id}_pills`;
    const container = document.querySelector(query);
    const element = pill(value);
    element.setAttribute(`${input.id}_pill`, "");
    container.appendChild(element);
  }
  function savePillsToState(input) {
    const query = `[pills-container]#${input.id}_pills`;
    const container = document.querySelector(query);
    let value = [];
    container.childNodes.forEach((child) => {
      value.push(child.textContent);
    });
    changePill(input, value);
  }
  var pillsLogic_default = pillsLogic;

  // src/js/form/renderForm.js
  var formContainer = document.querySelector("[data-form-root]");
  function renderInput(field) {
    switch (field.type) {
      case "textarea":
        return textarea(field, change);
      case "select":
        return select(field);
      case "radio":
        return radios(field);
      case "pills":
        return pills(field, pillsLogic_default);
      case "dynamicChecklist":
        return dynCL(field);
      default:
        return text(field, change);
    }
  }
  function renderField(field, fieldCounter) {
    const div = document.createElement("div");
    const input = renderInput(field);
    div.appendChild(input);
    fieldCounter++;
    return div;
  }
  function section(sId, sec) {
    const title = sec.title;
    const fields2 = sec.fields;
    const fieldset = document.createElement("fieldset");
    fieldset.id = sId;
    const legend = document.createElement("legend");
    legend.textContent = title;
    fieldset.appendChild(legend);
    let fieldCounter = 1;
    fields2.forEach((field) => {
      const input = renderField(field, fieldCounter);
      fieldset.appendChild(input);
      fieldCounter++;
    });
    formContainer.appendChild(fieldset);
  }
  function submit() {
    const submitBtn = document.createElement("input");
    submitBtn.type = "submit";
    submitBtn.value = "Enviar";
    formContainer.appendChild(submitBtn);
  }

  // src/js/form/initForm.js
  async function formInit() {
    const sections = await schema();
    Object.entries(sections).forEach(async (section2) => {
      const sId = section2[0];
      const sec = section2[1];
      if (sId === "identificacion") return;
      section(sId, sec);
    });
    submit();
  }

  // src/js/app.js
  formInit();
})();
